	FlipNumbers    bool     `yaml:"-" json:"-"`
	AddWords       bool     `yaml:"-" json:"-"`
	AddNumbers     bool     `yaml:"-" json:"-"`
	MinForWordFlip int      `yaml:"-" json:"-"`
	EditDistance   int      `yaml:"-" json:"-"`
