		}
	}
}

func TestFQDNFilterPrune(t *testing.T) {
	ff := NewFQDNFilter()
	defer ff.Close()

	limit := 50
	for i := 0; i < limit; i++ {
		fqdn := "www" + strconv.Itoa(i) + ".cs.utica.edu"
		ff.Insert(fqdn)
	}

	var found bool
	var name string
	ff.Prune(limit)
	for _, fqdn := range ff.Slice() {
		if fqdn == "www1.cs.utica.edu" {
			name = fqdn
			found = true
			break
		}
	}

	if found {
		t.Errorf("Passive DNS Filter Prune failed to remove the labels: %s", name)
	}
}

