func FullNameToPerson(raw string) *oampeop.Person {
	if raw == "" {
		return nil
	}

	if parts := strings.Split(raw, " "); len(parts) == 1 {
		return nil
	}

	name := fnparser.ParseFullname(raw)
	if name.First == "" || name.Last == "" {
		return nil
	}

	var fullname string
	if name.Title != "" {
		fullname += name.Title + " "
	}
	fullname += name.First + " "

	if name.Middle != "" {
		fullname += name.Middle + " "
	}
	fullname += name.Last

	if name.Suffix != "" {
		fullname += ", " + name.Suffix
	}

	return &oampeop.Person{
		ID:         fullname,
		FullName:   fullname,
		FirstName:  name.First,
		MiddleName: name.Middle,
		FamilyName: name.Last,
	}
}

func PhoneToOAMPhone(phone, ext, country string) *oamcon.Phone {
	if phone == "" {
		return nil
	}

	raw := phone
	if ext != "" {
		raw += " Ext. " + ext
	}

	num, err := phonenumbers.Parse(raw, country)
	if err != nil || !phonenumbers.IsValidNumber(num) {
		return nil
	}
	e164 := phonenumbers.Format(num, phonenumbers.E164)

	raw = e164
	ext = num.GetExtension()
	if ext != "" {
		raw += " Ext. " + ext
	}

	return &oamcon.Phone{
		Raw:           raw,
		E164:          e164,
		CountryAbbrev: strings.ToUpper(country),
		CountryCode:   int(num.GetCountryCode()),
		Ext:           ext,
	}
}

func RawURLToOAM(raw string) *oamurl.URL {
	if raw == "" {
		return nil
	}

	flags := purell.FlagLowercaseScheme | purell.FlagLowercaseHost | purell.FlagUppercaseEscapes
	flags |= purell.FlagDecodeDWORDHost | purell.FlagDecodeHexHost | purell.FlagDecodeOctalHost
	flags |= purell.FlagRemoveDuplicateSlashes | purell.FlagRemoveEmptyPortSeparator | purell.FlagRemoveUnnecessaryHostDots
	normalized, err := purell.NormalizeURLString(raw, flags)
	if err != nil {
		return nil
	}

	if u, err := url.Parse(normalized); err == nil && u != nil {
		ou := &oamurl.URL{
			Raw:      u.String(),
			Scheme:   u.Scheme,
			Username: u.User.Username(),
			Host:     u.Hostname(),
			Path:     u.Path,
			Fragment: u.Fragment,
		}
		if port := u.Port(); port != "" {
			if i, err := strconv.Atoi(port); err == nil {
				ou.Port = i
			}
		} else {
			ou.Port = schemeToPort(u.Scheme)
		}
		if pass, ok := u.User.Password(); ok && pass != "" {
			ou.Password = pass
		}
		return ou
	}
	return nil
}

func schemeToPort(scheme string) int {
	var port int

	switch scheme {
	case "ftp-data":
		port = 20
	case "ftp":
		port = 21
	case "ssh":
		port = 22
	case "telnet":
		port = 23
	case "smtp":
		port = 25
	case "domain":
		port = 53
	case "tftp":
		port = 69
	case "http":
		port = 80
	case "sftp":
		port = 115
	case "ntp":
		port = 123
	case "imap":
		port = 143
	case "snmp":
		port = 161
	case "print-srv":
		port = 170
