		if err != nil {
			t.Errorf("Unexpected error: %v", err)
		}
		expected := []byte(`{"seed":{},"scope":{"ports":[80,443]},"rigid_boundaries":false,"resolvers":null,"datasource_config":{},"transformations":{}}
`)

