		}
		if !reflect.DeepEqual(got, expected) {
			t.Errorf("Unexpected JSON bytes.\nExpected: %s\nGot: %s", expected, got)
		}

	})

	t.Run("TestActive fails to parse non-bool active setting", func(t *testing.T) {
