func splitLines(value string) []string {
	var lines []string
	start := 0
	for i := 0; i <= len(value); i++ {
		if i == len(value) || value[i] == '\n' {
			line := value[start:i]
			if len(line) > 0 && line[0] != '\r' {
				lines = append(lines, line)
			}
			start = i + 1
		}
	}
	return lines
}

