	mux := dns.NewServeMux()
	mux.HandleFunc(zone, func(w dns.ResponseWriter, r *dns.Msg) {
		if r.Question[0].Qtype == dns.TypeAXFR && allow {
			ch := make(chan *dns.Envelope, 1)
			transfer := new(dns.Transfer)
			go func() {
				ch <- &dns.Envelope{RR: records}
